function solve(input) {
  const map = new Map();
  const seen = new Set();
  for (const record of input) {
    if (seen.has(record.eventId)) continue;
    seen.add(record.eventId);
    const { account, delta } = record;
    const current = map.get(account) || 0;
    map.set(account, current + delta);
  }
  const result = [];
  for (const [account, balance] of map) {
    result.push([account, balance]);
  }
  result.sort((a, b) => {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    return 0;
  });
  return result;
}

