function solve(input) {
  const cache = new Map();
  const results = [];

  for (const op of input) {
    const { t, op: type } = op;

    if (type === "put") {
      const { key, value, ttl } = op;
      const expireAt = t + ttl;
      if (expireAt <= t) {
        cache.delete(key);
      } else {
        cache.set(key, { value, expireAt });
      }
    } else if (type === "get") {
      const { key } = op;
      const entry = cache.get(key);
      if (!entry || entry.expireAt <= t) {
        cache.delete(key);
        results.push(null);
      } else {
        results.push(entry.value);
      }
    } else if (type === "delete") {
      const { key } = op;
      cache.delete(key);
    }
  }

  return results;
}

